/// `Modules/ModParser.lua:3393-3396`
fn c3393(d: &ModParserData, _f: &FnRef, a: &[Value]) -> Result<Ret2, ParseError> {
    let v1_skill = arg(a, 1);
    let v2_num = arg(a, 2);
    Ok((
        seq(vec![
            call_mod(vec![
                Value::str("ExtraSkill"),
                Value::str("LIST"),
                tbl([
                    ("skillId", named_gem_id_lookup(d, &v1_skill)?),
                    ("level", Value::Num(1.0_f64)),
                    ("noSupports", Value::Bool(true)),
                    ("triggered", Value::Bool(true)),
                ]),
            ])?,
            call_mod(vec![
                Value::str("CurseEffect"),
                Value::str("INC"),
                tonumber(&v2_num),
                tbl([
                    ("type", Value::str("SkillName")),
                    (
                        "skillName",
                        str_sub(
                            &self_str(
                                &gsub_v(
                                    &check_str(&concat_v(&Value::str(" "), &v1_skill, "", "local 'skill'")?, 1, "gsub")?,
                                    &check_str(&Value::str("%W%l"), 2, "gsub")?,
                                    GsubRepl::Upper,
                                )?
                                .0,
                                "",
                            )?,
                            &Value::Num(2.0_f64),
                            &Value::Nil,
                        )?,
                    ),
                ]),
            ])?,
        ]),
        Value::Nil,
    ))
}

